// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testRegression_property() public {
        MintableToken stakingToken = new MintableToken();
        MintableToken rewardToken = new MintableToken();

        c = new StaxLPStaking(address(stakingToken), address(this));

        stakingToken.mint(address(this), 1 ether);
        stakingToken.approve(address(c), 1 ether);

        c.addReward(address(rewardToken));

        rewardToken.mint(address(this), 604800);
        rewardToken.approve(address(c), 604800);

        c.stake(1);

        c.notifyRewardAmount(address(rewardToken), 604800);

        vm.warp(block.timestamp + 604800);

        uint256 contractBalanceBefore = rewardToken.balanceOf(address(c));

        c.getRewards(address(this));

        uint256 balanceAfter = rewardToken.balanceOf(address(this));

        bool success = (balanceAfter > 0);
        assertTrue(success);
    }
}

contract MintableToken {
    string public name = "TestToken";
    string public symbol = "TST";
    uint8 public decimals = 18;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) public {
        totalSupply += amount;
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) public returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transfer(address to, uint256 amount) public returns (bool) {
        require(balanceOf[msg.sender] >= amount);
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) public returns (bool) {
        require(balanceOf[from] >= amount);
        require(allowance[from][msg.sender] >= amount);
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        allowance[from][msg.sender] -= amount;
        return true;
    }
}
